    out = [row[:] for row in grid]
    pts = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    rows = {}
    cols = {}
    for r,c in pts:
        rows.setdefault(r,[]).append(c)
        cols.setdefault(c,[]).append(r)
    # Connect marker rows in the main horizontal band and extend vertical
    # branches from each marker to the nearest marker on the same column.
    multi = [r for r,cs in rows.items() if len(cs)>1]
    if multi:
        r = max(multi, key=lambda rr: len(rows[rr]))
        for c in range(min(rows[r])+1,max(rows[r])):
            if out[r][c]==0: out[r][c]=3
    for c,rs in cols.items():
        rs.sort()
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if out[r][c]==0: out[r][c]=3
    # Each off-band marker is joined to the main bar at its column.
    if multi:
        r0 = max(multi, key=lambda rr: len(rows[rr]))
        for r,c in pts:
            if r != r0 and min(rows[r0]) <= c <= max(rows[r0]):
                for rr in range(min(r,r0)+1,max(r,r0)):
                    if out[rr][c]==0: out[rr][c]=3
    return out
