 "content": "def transform(grid):
    out = [row[:] for row in grid]
    pts = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    # The alignments define one vertical trunk and horizontal branches. The
    # trunk is the column with the greatest number of markers; each marker
    # connects horizontally to that trunk, and trunk markers connect vertically.
    from collections import Counter
    cc=Counter(c for r,c in pts)
    trunk=max(cc, key=lambda c:(cc[c],-c))
    rs=[r for r,c in pts if c==trunk]
    for a,b in zip(sorted(rs),sorted(rs)[1:]):
        for r in range(a+1,b):
            if out[r][trunk]==0: out[r][trunk]=3
    for r,c in pts:
        if c != trunk:
            for x in range(min(c,trunk)+1,max(c,trunk)):
                if out[r][x]==0: out[r][x]=3
    return out
